// Create a client: "What are you building?" first (the app type preselects the settings), then the
// form. A confidential client's secret is generated by the server, shown once here and
// kept only in this page's state (the mutation result holds the client without the secret).
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { Link, createFileRoute } from "@tanstack/react-router";
import { useState } from "react";
import { api, unwrap } from "@/api/client";
import { useTenant } from "@/lib/tenant";
import { ClientForm, type ClientFormValues, createBody, newClientValues } from "@/components/ClientForm";
import { OneTimeSecret } from "@/components/WebhookForm";

const linkClass =
  "text-sm underline-offset-4 hover:underline focus-visible:ring-[3px] focus-visible:ring-ring/50 focus-visible:outline-none";

// One object for the page's lifetime: the form's unsaved-changes baseline compares against it.
const INITIAL = newClientValues("web");

function NewClientPage() {
  const tenant = useTenant();
  const queryClient = useQueryClient();
  const [secret, setSecret] = useState<string | null>(null);
  // Whether the created client had a secret (it stays true after the secret is dismissed).
  const [hadSecret, setHadSecret] = useState(false);
  const create = useMutation({
    mutationFn: async (values: ClientFormValues) => {
      const { client_secret, ...client } = unwrap(
        await api.POST("/api/admin/v1/tenants/{slug}/clients", {
          params: { path: { slug: tenant } },
          body: createBody(values),
        }),
      );
      // The secret goes to component state only; the cached mutation result is the client.
      setSecret(client_secret ?? null);
      setHadSecret(Boolean(client_secret));
      return client;
    },
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: ["clients"] });
    },
  });

  const created = create.data;

  return (
    <section aria-labelledby="new-client-heading" className="space-y-4">
      <Link to="/t/$tenant/clients" params={{ tenant }} className={`text-muted-foreground ${linkClass}`}>
        ← Clients
      </Link>
      <h1 id="new-client-heading" className="text-xl font-semibold">
        {created ? "Client created" : "New client"}
      </h1>
      {created ? (
        <div className="space-y-4">
          <p role="status" className="text-sm">
            Client <code data-testid="created-client-id">{created.client_id}</code> created.
            {!hadSecret && " It has no secret."}
          </p>
          {secret ? (
            <OneTimeSecret
              title="Copy the client secret now. It is not shown again."
              label="Client secret"
              value={secret}
              testId="created-client-secret"
              onDone={() => setSecret(null)}
            />
          ) : (
            hadSecret && (
              <p className="text-muted-foreground text-sm" data-testid="created-client-secret-gone">
                The secret is no longer shown. Rotate it on the client page if it was lost.
              </p>
            )
          )}
          <div className="flex gap-4">
            <Link
              to="/t/$tenant/clients/$clientId"
              params={{ tenant, clientId: created.client_id }}
              className={linkClass}
            >
              Open {created.name}
            </Link>
            <Link to="/t/$tenant/clients" params={{ tenant }} className={linkClass}>
              Back to clients
            </Link>
          </div>
        </div>
      ) : (
        <ClientForm
          mode="create"
          initial={INITIAL}
          initialAppType="web"
          submitLabel="Create client"
          pending={create.isPending}
          error={create.error}
          onSubmit={(values) => create.mutate(values)}
        />
      )}
    </section>
  );
}

export const Route = createFileRoute("/t/$tenant/clients/new")({ component: NewClientPage });
